import 'package:flutter/material.dart';
import '../../../services/auth/auth_service.dart';
import '../../../services/personal_ai/weekly_review_service.dart';
class AurenWeeklyReviewScreen extends StatefulWidget{const AurenWeeklyReviewScreen({super.key});@override State<AurenWeeklyReviewScreen> createState()=>_AurenWeeklyReviewScreenState();}
class _AurenWeeklyReviewScreenState extends State<AurenWeeklyReviewScreen>{final _auth=FirebaseAurenAuthService();final _service=WeeklyReviewService();AurenWeeklyReview? _review;bool _loading=false;
Future<void> _build()async{final uid=_auth.currentUserId;if(uid==null)return;setState(()=>_loading=true);try{final r=await _service.build(uid);if(mounted)setState(()=>_review=r);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر إنشاء مراجعة الأسبوع: '+e.toString())));}finally{if(mounted)setState(()=>_loading=false);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Weekly Review')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('مراجعة أسبوعك مع AUREN',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('صورة مختصرة تساعدك على معرفة وضعك واختيار التركيز للأسبوع القادم.'),const SizedBox(height:20),FilledButton.icon(onPressed:_loading?null:_build,icon:_loading?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.date_range),label:Text(_loading?'جاري التحليل…':'أنشئ مراجعة الأسبوع')),if(_review!=null)...[const SizedBox(height:20),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_review!.headline,style:const TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:12),Text('التركيز للمراجعة: '+_review!.focus),Text('أهداف نشطة: '+_review!.activeGoals.toString()),Text('أهداف مكتملة: '+_review!.completedGoals.toString()),Text('ذكريات مفعّلة: '+_review!.enabledMemories.toString()),Text('متوسط التقدم: '+_review!.averageProgress.toString()+'%')])))] ]));}